24 | // NewIssue creates new issue with labels for repository.
25 | func NewIssue(ctx context.Context, repo *repo_model.Repository, issue *issues_model.Issue, labelIDs []int64, uuids []string, assigneeIDs, projectIDs []int64) error {
26 | 	if err := issue.LoadPoster(ctx); err != nil {
27 | 		return err
28 | 	}
29 | 
30 | 	if user_model.IsUserBlockedBy(ctx, issue.Poster, repo.OwnerID) || user_model.IsUserBlockedBy(ctx, issue.Poster, assigneeIDs...) {
31 | 		return user_model.ErrBlockedUser
32 | 	}
33 | 
34 | 	assigneeCommentMap := make(map[int64]*issues_model.Comment)
35 | 	assignees := make(map[int64]*user_model.User)
36 | 	if err := db.WithTx(ctx, func(ctx context.Context) error {
37 | 		if err := issues_model.NewIssue(ctx, repo, issue, labelIDs, uuids); err != nil {
38 | 			return err
39 | 		}
40 | 		for _, assigneeID := range assigneeIDs {
41 | 			assignee, err := user_model.GetUserByID(ctx, assigneeID)
42 | 			if err != nil {
43 | 				log.Error("GetUserByID: %v", err)
44 | 				continue
45 | 			}
46 | 			assignees[assigneeID] = assignee
47 | 			comment, err := AddAssigneeIfNotAssigned(ctx, issue, issue.Poster, assignee)
48 | 			if err != nil {
49 | 				return err
50 | 			}
51 | 			assigneeCommentMap[assigneeID] = comment
52 | 		}
53 | 		if len(projectIDs) > 0 {
54 | 			err := issues_model.IssueAssignOrRemoveProject(ctx, issue, issue.Poster, projectIDs)
55 | 			if err != nil {
56 | 				return err
57 | 			}
58 | 		}
59 | 		return nil
60 | 	}); err != nil {
61 | 		return err
62 | 	}
63 | 
64 | 	mentions, err := issues_model.FindAndUpdateIssueMentions(ctx, issue, issue.Poster, issue.Content)
65 | 	if err != nil {
66 | 		return err
67 | 	}
68 | 
69 | 	notify_service.NewIssue(ctx, issue, mentions)
70 | 	if len(issue.Labels) > 0 {
71 | 		notify_service.IssueChangeLabels(ctx, issue.Poster, issue, issue.Labels, nil)
72 | 	}
73 | 	if issue.Milestone != nil {
74 | 		notify_service.IssueChangeMilestone(ctx, issue.Poster, issue, 0)
75 | 	}
76 | 
77 | 	if len(assigneeIDs) > 0 {
78 | 		for _, assignee := range assignees {
79 | 			notify_service.IssueChangeAssignee(ctx, issue.Poster, issue, assignee, false, assigneeCommentMap[assignee.ID])
80 | 		}
81 | 	}
82 | 
83 | 	return nil
84 | }
